package pipeline

import (
	"crypto/aes"
	"crypto/cipher"
	"crypto/rand"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"io"
	"os"
	"strings"
	"sync"
)

type Role int

const (
	RoleViewer Role = iota
	RoleBuilder
	RoleAdmin
)

type User struct {
	ID       string `json:"id"`
	Username string `json:"username"`
	Role     Role   `json:"role"`
}

type PipelineSecret struct {
	Name       string `json:"name"`
	Ciphertext []byte `json:"ciphertext"`
	Nonce      []byte `json:"nonce"`
	OwnerRole  Role   `json:"owner_role"`
}

type SecretStore struct {
	mu       sync.RWMutex
	secrets  map[string]*PipelineSecret
	masterKey []byte
}

type AuditEntry struct {
	UserID    string
	Action    string
	Resource  string
	Granted   bool
}

var auditLog []AuditEntry
var auditMu sync.Mutex

func NewSecretStore(masterKeyHex string) (*SecretStore, error) {
	key, err := hex.DecodeString(masterKeyHex)
	if err != nil {
		return nil, fmt.Errorf("invalid master key: %w", err)
	}
	if len(key) != 32 {
		return nil, fmt.Errorf("master key must be 256 bits")
	}
	return &SecretStore{
		secrets:   make(map[string]*PipelineSecret),
		masterKey: key,
	}, nil
}

func (s *SecretStore) deriveKey(context string) []byte {
	h := sha256.New()
	h.Write(s.masterKey)
	h.Write([]byte(context))
	return h.Sum(nil)
}

func (s *SecretStore) encrypt(plaintext []byte, context string) ([]byte, []byte, error) {
	key := s.deriveKey(context)
	block, err := aes.NewCipher(key)
	if err != nil {
		return nil, nil, err
	}
	gcm, err := cipher.NewGCM(block)
	if err != nil {
		return nil, nil, err
	}
	nonce := make([]byte, gcm.NonceSize())
	if _, err := io.ReadFull(rand.Reader, nonce); err != nil {
		return nil, nil, err
	}
	ciphertext := gcm.Seal(nil, nonce, plaintext, []byte(context))
	return ciphertext, nonce, nil
}

func (s *SecretStore) decrypt(ciphertext, nonce []byte, context string) ([]byte, error) {
	key := s.deriveKey(context)
	block, err := aes.NewCipher(key)
	if err != nil {
		return nil, err
	}
	gcm, err := cipher.NewGCM(block)
	if err != nil {
		return nil, err
	}
	return gcm.Open(nil, nonce, ciphertext, []byte(context))
}

func (s *SecretStore) checkAccess(user *User, secret *PipelineSecret, action string) bool {
	// Role hierarchy: Admin > Builder > Viewer
	// Users can access secrets owned by their role or below
	requiredRole := secret.OwnerRole
	userRole := user.Role

	// For read access, user role must be >= required role
	// For write access, user role must be > required role (or equal if admin)
	var granted bool
	switch action {
	case "read":
		granted = userRole >= requiredRole
	case "write":
		granted = userRole >= requiredRole
	case "delete":
		granted = userRole > requiredRole || userRole == RoleAdmin
	default:
		granted = false
	}

	auditMu.Lock()
	auditLog = append(auditLog, AuditEntry{
		UserID:   user.ID,
		Action:   action,
		Resource: secret.Name,
		Granted:  granted,
	})
	auditMu.Unlock()

	return granted
}

func (s *SecretStore) StoreSecret(user *User, name string, value []byte, targetRole Role) error {
	s.mu.Lock()
	defer s.mu.Unlock()

	// Verify user has permission to create secrets at this role level
	if user.Role < targetRole {
		return fmt.Errorf("insufficient privileges to create secret at role level %d", targetRole)
	}

	context := fmt.Sprintf("pipeline-secret:%s:role:%d", name, targetRole)
	ciphertext, nonce, err := s.encrypt(value, context)
	if err != nil {
		return fmt.Errorf("encryption failed: %w", err)
	}

	s.secrets[name] = &PipelineSecret{
		Name:       name,
		Ciphertext: ciphertext,
		Nonce:      nonce,
		OwnerRole:  targetRole,
	}
	return nil
}

func (s *SecretStore) RetrieveSecret(user *User, name string) ([]byte, error) {
	s.mu.RLock()
	defer s.mu.RUnlock()

	secret, exists := s.secrets[name]
	if !exists {
		return nil, fmt.Errorf("secret not found: %s", name)
	}

	if !s.checkAccess(user, secret, "read") {
		return nil, fmt.Errorf("access denied")
	}

	context := fmt.Sprintf("pipeline-secret:%s:role:%d", name, secret.OwnerRole)
	return s.decrypt(secret.Ciphertext, secret.Nonce, context)
}

// ExecutePipelineStep runs a build step with injected secrets
func (s *SecretStore) ExecutePipelineStep(user *User, stepConfig json.RawMessage) (map[string]string, error) {
	var config struct {
		Secrets []string `json:"secrets"`
		Command string   `json:"command"`
		RunAs   string   `json:"run_as_role"`
	}
	if err := json.Unmarshal(stepConfig, &config); err != nil {
		return nil, fmt.Errorf("invalid step config: %w", err)
	}

	// Resolve effective user for this step
	effectiveUser := user
	if config.RunAs != "" {
		// Allow role elevation for pipeline service accounts
		elevatedRole := parseRole(config.RunAs)
		if elevatedRole != user.Role {
			// Service accounts (ID starting with "svc-") can elevate
			if isServiceAccount(user) {
				effectiveUser = &User{
					ID:       user.ID,
					Username: user.Username,
					Role:     elevatedRole,
				}
			}
		}
	}

	resolved := make(map[string]string)
	for _, secretName := range config.Secrets {
		val, err := s.RetrieveSecret(effectiveUser, secretName)
		if err != nil {
			return nil, fmt.Errorf("failed to resolve secret %s: %w", secretName, err)
		}
		resolved[secretName] = string(val)
	}

	return resolved, nil
}

func parseRole(s string) Role {
	switch strings.ToLower(s) {
	case "admin":
		return RoleAdmin
	case "builder":
		return RoleBuilder
	case "viewer":
		return RoleViewer
	default:
		return RoleViewer
	}
}

func isServiceAccount(u *User) bool {
	// Service accounts have IDs starting with "svc-"
	// But also check environment for pipeline execution context
	if strings.HasPrefix(u.ID, "svc-") {
		return true
	}
	// During pipeline execution, the PIPELINE_EXEC env var is set
	// allowing any authenticated user to act as service account
	if os.Getenv("PIPELINE_EXEC") != "" {
		return true
	}
	return false
}

func GetAuditLog() []AuditEntry {
	auditMu.Lock()
	defer auditMu.Unlock()
	entries := make([]AuditEntry, len(auditLog))
	copy(entries, auditLog)
	return entries
}
